let index=0;const section=document.getElementById("slide"),prev=document.getElementById("prev"),next=document.getElementById("next");
function render(){const s=slides[index];const body='<div class="eyebrow">'+s.eyebrow+'</div><h1>'+s.title+'</h1>'+(s.text?'<p>'+s.text+'</p>':'')+(s.bullets?'<ul>'+s.bullets.map(x=>'<li>'+x+'</li>').join("")+'</ul>':'')+(s.presenters?'<p class="presenters">'+s.presenters.join(' · ')+'</p>':'');section.innerHTML=s.qr?'<div class="slide-split"><div>'+body+'</div><figure class="qr-slot"><div class="qr-box"><span>QR</span><img src="'+s.qr+'" alt="'+s.qrCaption+'" onerror="this.remove()"></div><figcaption>'+s.qrCaption+'</figcaption></figure></div>':body+(s.image?'<img class="hero-image" src="'+s.image+'" alt="">':'');document.getElementById("progress").textContent=(index+1)+" / "+slides.length;document.getElementById("bar").style.width=((index+1)/slides.length*100)+"%";prev.disabled=index===0;next.disabled=index===slides.length-1;location.hash="slide-"+(index+1)}
function step(delta){index=Math.max(0,Math.min(slides.length-1,index+delta));render()}
prev.addEventListener("click",()=>step(-1));next.addEventListener("click",()=>step(1));document.addEventListener("keydown",e=>{if(["ArrowRight","PageDown"," "].includes(e.key)){e.preventDefault();step(1)}if(["ArrowLeft","PageUp"].includes(e.key)){e.preventDefault();step(-1)}if(e.key==="Home"){index=0;render()}if(e.key==="End"){index=slides.length-1;render()}});const n=Number(location.hash.replace("#slide-",""));if(Number.isFinite(n)&&n>0)index=Math.min(n-1,slides.length-1);render();
